remediation.codeExample:
import { Button } from '@holmdigital/components';

// Bad: Poor contrast
<button style={{ background: '#777', color: '#999' }}>Click me</button>

// Good: Use accessible component
<Button variant="primary">Click me</Button>

// Bad: Div with onClick
<div onClick={handleClick}>Click Me</div>

// Good: Button element
<button onClick={handleClick}>Click Me</button>

// Best: Use HolmDigital component
import { Button } from '@holmdigital/components';
<Button onClick={handleClick}>Click Me</Button>

// Bad: Msising alt
<img src="logo.png" />

// Good: Descriptive alt
<img src="logo.png" alt="HolmDigital Logo" />

// Good: Decorative image
<img src="decoration.png" alt="" role="presentation" />

import { FormField } from '@holmdigital/components';

// Bad: No label
<input type="text" placeholder="Name" />

// Good: With label
<label htmlFor="name">Name:</label>
<input type="text" id="name" />

// Best: Use HolmDigital component
<FormField
  label="Name"
  type="text"
  required
  helpText="Enter your full name"
/>

// Bad: Generic title
<title>Page</title>

// Good: Descriptive title
<title>Contact Us - HolmDigital</title>

// React/Next.js
import Head from 'next/head';

<Head>
  <title>Contact Us - HolmDigital</title>
</Head>

import { ProgressBar } from '@holmdigital/components';

// Slecht: Div zonder rol
<div style={{ width: '50%' }}>50%</div>

// Goed: Toegankelijke component
<ProgressBar value={50} label="Laden..." />

import { LiveRegion } from '@holmdigital/components';

// Assertive voor fouten
<LiveRegion politeness="assertive">Fout: Opslaan mislukt.</LiveRegion>

// Polite voor statusupdates
<LiveRegion politeness="polite">Succesvol opgeslagen.</LiveRegion>

/* Insufficient hit area */
.icon-button { width: 16px; height: 16px; }

/* Good: 24px hit area via min-height/min-width */
.icon-button {
  min-width: 24px;
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* Good: small icon, but 24px clearance around it (spacing exception) */
.icon-button { margin: 4px; } /* yields >=24px center-to-center to the neighbour */
